"""Build the reference JSON from maintained, topic-specific editorial records.

No remote model or network is used. Run from the repository root with Python.
Examples and implementation advice are original illustrative practitioner guidance.
"""
import hashlib
import json
import re
from collections import Counter
from pathlib import Path

ROOT = Path(__file__).resolve().parent
TOPICS = []


def add(category, source, rows):
    for line in rows.strip().splitlines():
        fields = [part.strip() for part in line.split("|")]
        if len(fields) != 10:
            raise ValueError(f"Expected 10 fields, got {len(fields)}: {line}")
        label, question, direct, detail, example, practice, mistake, evidence, assess, related = fields
        TOPICS.append(dict(category=category, source=source, label=label,
                           question=question, direct=direct, detail=detail,
                           example=example, practice=practice, mistake=mistake,
                           evidence=evidence, assess=assess,
                           related=[item.strip() for item in related.split(";")]))


